const studentJS=String.raw`
'use strict';
const QUESTIONS=__QUESTIONS__,WRITING=__WRITING__,NAMES=__NAMES__,VERSION=__VERSION__;
const KEY='edussentials.economics.explore.v2';const $=id=>document.getElementById(id);
let state={answers:{},writing:{},attempts:[],hints:[],step:0},checked=new Set(),saveFailed=false,wasRestored=false;
try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw&&typeof raw==='object'){state.answers=raw.answers&&typeof raw.answers==='object'?raw.answers:{};state.writing=raw.writing&&typeof raw.writing==='object'?raw.writing:{};state.attempts=Array.isArray(raw.attempts)?raw.attempts:[];state.hints=Array.isArray(raw.hints)?raw.hints:[];state.step=Number.isInteger(raw.step)&&raw.step>=0&&raw.step<6?raw.step:0;wasRestored=true;}else{const old=JSON.parse(localStorage.getItem('edussentials.economics.pricing.preview.v1')||'null');if(old&&old.entries){for(const q of QUESTIONS)if(typeof old.entries[q.id]==='string')state.answers[q.id]=old.entries[q.id];if(['400','500','600'].includes(old.price))state.answers['price-choice']=String(['400','500','600'].indexOf(old.price));wasRestored=Object.keys(state.answers).length>0;}}}catch{saveFailed=true;}
function parse(v){if(typeof v!=='string'||!v.trim())return null;const s=v.trim().replace(/−/g,'-').replace(/[₹,\s]/g,'');if(!/^-?\d+(\.\d+)?$/.test(s))return NaN;return Number(s);}
function result(q){const raw=typeof state.answers[q.id]==='string'?state.answers[q.id]:'';if(!raw.trim())return 'missing';return q.type==='number'?(parse(raw)===q.answer?'correct':'incorrect'):(raw===String(q.answer)?'correct':'incorrect');}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saveFailed=false;$('save-status').textContent='Saved on this browser · download to keep a copy';}catch{saveFailed=true;$('save-status').textContent='Browser saving unavailable · download your work before leaving';}progress();}
function progress(){const count=QUESTIONS.filter(q=>String(state.answers[q.id]||'').trim()).length;const total=QUESTIONS.length;$('overall').textContent=count+' of '+total+' checkable answers entered · writing uses a self-review checklist';$('side-progress').textContent=count+' / '+total+' answers entered';$('progressfill').style.width=(count/total*100)+'%';for(let s=1;s<=4;s++){const qs=QUESTIONS.filter(q=>q.step===s);const answered=qs.filter(q=>String(state.answers[q.id]||'').trim()).length;$('nav-status-'+s).textContent=answered+' / '+qs.length+' entered';}const done=WRITING.filter(q=>q.required&&String(state.writing[q.id]||'').trim()).length;$('nav-status-5').textContent=done+' / '+WRITING.filter(q=>q.required).length+' written responses';}
function showStep(n,focus=true){state.step=n;document.querySelectorAll('[data-panel]').forEach(el=>el.hidden=Number(el.dataset.panel)!==n);document.querySelectorAll('[data-step]').forEach(el=>{if(Number(el.dataset.step)===n)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});$('previous').disabled=n===0;$('next').hidden=n===5;$('next').textContent=(NAMES[n+1]||'')+' →';if(focus){save();const heading=document.querySelector('[data-panel="'+n+'"] h2');heading.focus({preventScroll:true});heading.scrollIntoView({behavior:'instant',block:'start'});}}
function clearCompletion(){$('completion-message').textContent='';$('scorecard').replaceChildren();}
for(const q of QUESTIONS){const el=$(q.id);el.value=typeof state.answers[q.id]==='string'?state.answers[q.id]:'';el.addEventListener('input',()=>{state.answers[q.id]=el.value;el.removeAttribute('aria-invalid');el.removeAttribute('data-correct');$(q.id+'-feedback').textContent='';if(checked.has(q.step))$('result-'+q.step).textContent='Your answers have changed. Check this stage again when ready.';clearCompletion();save();});}
for(const w of WRITING){$(w.id).value=typeof state.writing[w.id]==='string'?state.writing[w.id]:'';$(w.id).addEventListener('input',()=>{state.writing[w.id]=$(w.id).value;clearCompletion();save();});}
function checkStep(s,record=true){checked.add(s);const qs=QUESTIONS.filter(q=>q.step===s);let correct=0,missing=0;for(const q of qs){const r=result(q),f=$(q.id+'-feedback'),el=$(q.id);if(r==='correct'){correct++;f.textContent='✓ Correct';f.className='feedback ok';el.setAttribute('data-correct','true');el.setAttribute('aria-invalid','false');}else{if(r==='missing')missing++;f.textContent=r==='missing'?'Add your answer.':q.hint;f.className='feedback';el.removeAttribute('data-correct');el.setAttribute('aria-invalid','true');}}const message=$('result-'+s);message.textContent=correct===qs.length?'All '+qs.length+' answers are correct. You can move to the next step.':correct+' of '+qs.length+' answers correct. '+(missing?missing+' still need an answer. ':'')+'Use the feedback and try again.';message.className='summary'+(correct===qs.length?' ok':'');if(record){state.attempts.push({time:new Date().toISOString(),stage:NAMES[s],score:correct,total:qs.length,answers:Object.fromEntries(qs.map(q=>[q.id,state.answers[q.id]||'']))});save();}return {correct,total:qs.length};}
document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>showStep(Number(b.dataset.step))));$('previous').addEventListener('click',()=>showStep(Math.max(0,state.step-1)));$('next').addEventListener('click',()=>showStep(Math.min(5,state.step+1)));document.querySelectorAll('[data-check]').forEach(b=>b.addEventListener('click',()=>checkStep(Number(b.dataset.check))));document.querySelectorAll('[data-hint]').forEach(d=>d.addEventListener('toggle',()=>{if(d.open&&!state.hints.includes(d.dataset.hint)){state.hints.push(d.dataset.hint);save();}}));
$('complete').addEventListener('click',()=>{const scores=[1,2,3,4].map(s=>({stage:s,...checkStep(s,false)}));const correct=scores.reduce((n,s)=>n+s.correct,0),required=WRITING.filter(w=>w.required&&!String(state.writing[w.id]||'').trim());const m=$('completion-message');m.className='summary'+(correct===QUESTIONS.length&&!required.length?' ok':'');m.textContent=correct===QUESTIONS.length&&!required.length?'Your case answers are correct and every required written response has an entry. Review your writing with the checklist, then export your work. Your writing and career interests have not been automatically assessed.':correct+' of '+QUESTIONS.length+' checkable answers correct. '+(required.length?required.length+' required written responses still need an entry. ':'')+'Use the stage summary below to revisit your work.';const list=document.createElement('ul');scores.forEach(s=>{const li=document.createElement('li');li.textContent=NAMES[s.stage]+': '+s.correct+' / '+s.total;list.appendChild(li);});required.forEach(w=>{const li=document.createElement('li');li.textContent='Still to write: '+w.label;list.appendChild(li);});$('scorecard').replaceChildren(list);state.attempts.push({time:new Date().toISOString(),stage:'Final review',score:correct,total:QUESTIONS.length,answers:{...state.answers}});save();});
function download(){const text=['EDUSSENTIALS CONSULTING','Career Lab Explore: Economics & Finance',VERSION,'Exported: '+new Date().toLocaleString(),'FICTIONAL BRIGHTBRIDGE CASE — STUDENT WORK','',...Array.from({length:4},(_,i)=>i+1).flatMap(s=>['STEP '+(s+1)+': '+NAMES[s],...QUESTIONS.filter(q=>q.step===s).map(q=>{const a=state.answers[q.id];return q.label+'\n'+(a===undefined||a===''?'[Not answered]':q.type==='choice'?(q.options[Number(a)]||'[Invalid choice]'):a)+'\n';})]),'WRITTEN RESPONSES',...WRITING.map(w=>w.label+'\n'+(state.writing[w.id]||'[Not written]')+'\n'),'CHECK HISTORY',...state.attempts.map((a,i)=>'Attempt '+(i+1)+' | '+a.time+' | '+a.stage+' | '+a.score+'/'+a.total+'\n'+Object.entries(a.answers || {}).filter(([,v])=>v!=='').map(([id,v])=>{const q=QUESTIONS.find(q=>q.id===id);return (q?.label||id)+': '+(q?.type==='choice'?q.options[Number(v)]:v);}).join('\n')),'','HELP OPENED: '+(state.hints.join(', ')||'None recorded'),'','This is self-paced practice. Written reasoning uses a self-review checklist; reflection has no right answer. No work is automatically submitted.'].join('\n');$('report-text').value=text;$('report-dialog').showModal();const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Economics Explore - My Work.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('toast').textContent='Download prepared. Keep the file for your review.';setTimeout(()=>$('toast').textContent='',3500);}
document.querySelectorAll('[data-download]').forEach(b=>b.addEventListener('click',download));$('print').addEventListener('click',()=>window.print());$('reset').addEventListener('click',()=>$('reset-dialog').showModal());$('cancel-reset').addEventListener('click',()=>$('reset-dialog').close());$('confirm-reset').addEventListener('click',()=>{state={answers:{},writing:{},attempts:[],hints:[],step:0};checked.clear();document.querySelectorAll('[data-answer],[data-writing]').forEach(el=>{el.value='';el.removeAttribute('aria-invalid');el.removeAttribute('data-correct');});document.querySelectorAll('.feedback,.summary').forEach(el=>el.textContent='');document.querySelectorAll('details[open]').forEach(el=>el.open=false);$('scorecard').replaceChildren();save();$('reset-dialog').close();showStep(0);});
showStep(state.step,false);progress();if(saveFailed)$('save-status').textContent='Browser saving unavailable · download your work before leaving';else if(wasRestored)$('save-status').textContent='Restored your work on this browser';
`.replace('__QUESTIONS__',JSON.stringify(questions)).replace('__WRITING__',JSON.stringify(writing)).replace('__NAMES__',JSON.stringify(stepNames)).replace('__VERSION__',JSON.stringify(VERSION));
const reportDialog='<dialog id="report-dialog" aria-labelledby="report-title"><h2 id="report-title">Your work, ready to keep.</h2><p class="small">A text download has been prepared. If your browser does not save it, select and copy the record below into a document.</p><div class="field"><label for="report-text">Your complete work record</label><textarea id="report-text" readonly style="height:300px"></textarea></div><div class="actions"><button class="button secondary" id="select-report">Select all text</button><button class="button" id="close-report">Back to workbook</button></div></dialog>';
const reportHandlers="$('close-report').addEventListener('click',()=>$('report-dialog').close());$('select-report').addEventListener('click',()=>{$('report-text').focus();$('report-text').select();});";
fs.writeFileSync(path.join(out,'index.html'),html('Career Lab Explore: Economics & Finance',studentBody.replace('<div id="toast"',reportDialog+'<div id="toast"'),studentJS+reportHandlers));
